// EVERY verification / one-time code in Sarab goes through deliverCode(): it is sent to the operator's
// Telegram chat by the notifier (the only container with internet access). Codes are never shown on
// screen, returned to staff, or generated by an authenticator app. Any new kind of code MUST use this.
//
// Each message says which account / national ID the code is for, what it is for, and when it expires.
// The wording lives in packages/shared/src/telegram-text.ts; the notifier, not Mithaq, turns it into text.
// Per-recipient send limit: one code per 60 seconds for the same key (e.g. "login:1100000015").
//
// Automated tests cannot read Telegram. An operator with shell access mints a short-lived test ticket
// (services/identity/src/test-ticket.ts); a request carrying it in header x-sarab-test-ticket gets the code
// back as `test_code` (and the full message text as `test_message`) instead of a Telegram message.
import type { PoolClient } from 'pg';
import { sha256hex } from '#shared/crypto.ts';
import { httpError } from '#shared/http.ts';
import { CODE_HEADING, codeRequestProblem, codeText, type CodeRequest } from '#shared/telegram-text.ts';

export { CODE_HEADING };
export const RESEND_SECONDS = 60;
const ORIGIN = process.env.PUBLIC_ORIGIN ?? 'http://localhost';

/**
 * A code to deliver. Mithaq sends only these structured fields; the notifier builds the message from fixed
 * templates (packages/shared/src/telegram-text.ts), so Mithaq cannot put arbitrary text in the chat.
 */
export interface CodeMessage extends CodeRequest {
  /** Rate-limit key: kind + recipient, e.g. "login:staff:clerk", "counter:1100000015". */
  key: string;
}

/** Ask the notifier to deliver a code message (it builds the text). */
async function sendCode(m: CodeRequest, lane: 'staff' | 'citizen'): Promise<boolean> {
  try {
    const r = await fetch(`${process.env.NOTIFIER_URL}/send`, {
      method: 'POST', headers: { 'content-type': 'application/json', 'x-notifier-key': process.env.NOTIFIER_KEY ?? '' },
      body: JSON.stringify({ ...m, lane }), signal: AbortSignal.timeout(15_000),
    });
    return r.ok;
  } catch { return false; }
}

const request = ({ key: _key, ...r }: CodeMessage): CodeRequest => ({ ...r, expires_at: new Date(r.expires_at).toISOString() });

/** True when the request carries a valid, unused test ticket (nothing is consumed). */
export async function hasTestTicket(c: { query: PoolClient['query'] }, req: { headers: Record<string, unknown> }): Promise<boolean> {
  const t = req.headers['x-sarab-test-ticket'];
  if (typeof t !== 'string' || t.length < 32) return false;
  return (await c.query('SELECT 1 FROM staff_test_tickets WHERE ticket_hash = $1 AND uses_left > 0 AND expires_at > now()', [sha256hex(t)])).rowCount === 1;
}

/** True (and one use is consumed) when the request carries a valid test ticket. */
async function testTicket(c: PoolClient, req: { headers: Record<string, unknown> }): Promise<boolean> {
  const t = req.headers['x-sarab-test-ticket'];
  if (typeof t !== 'string' || t.length < 32) return false;
  return (await c.query(
    'UPDATE staff_test_tickets SET uses_left = uses_left - 1 WHERE ticket_hash = $1 AND uses_left > 0 AND expires_at > now() RETURNING 1', [sha256hex(t)],
  )).rowCount === 1;
}

/**
 * Deliver a code. Call it INSIDE the transaction that stores the code's hash: if the 60-second limit
 * applies (429 code_recently_sent) or Telegram cannot be reached (503 code_not_sent), it throws and the
 * transaction — including the stored code — is rolled back.
 */
export async function deliverCode(c: PoolClient, req: { headers: Record<string, unknown>; log?: any }, m: CodeMessage): Promise<{ test_code?: string; test_message?: string }> {
  const r = request(m);
  const problem = codeRequestProblem(r);
  if (problem) throw new Error(`code message would be refused by the notifier: ${problem}`);
  const test = await testTicket(c, req);
  if (test) {
    // Tests are exempt from the limit, but still count as "a code was just sent" for everyone else.
    await c.query('INSERT INTO code_sends (key, sent_at) VALUES ($1, now()) ON CONFLICT (key) DO UPDATE SET sent_at = now()', [m.key]);
  } else {
    // One code per key per 60 s, claimed atomically (parallel requests wait on the row lock, then fail).
    const claimed = (await c.query(
      `INSERT INTO code_sends (key, sent_at) VALUES ($1, now())
       ON CONFLICT (key) DO UPDATE SET sent_at = now() WHERE code_sends.sent_at < now() - make_interval(secs => $2)
       RETURNING 1`, [m.key, RESEND_SECONDS],
    )).rowCount === 1;
    if (!claimed) {
      const { rows: [w] } = await c.query(
        'SELECT ceil(extract(epoch FROM sent_at + make_interval(secs => $2) - now()))::int AS s FROM code_sends WHERE key = $1', [m.key, RESEND_SECONDS]);
      const wait = Math.max(1, w?.s ?? RESEND_SECONDS);
      throw httpError(429, 'code_recently_sent', `A code was sent less than a minute ago. Use it, or wait ${wait} seconds for a new one.`, { retry_after: wait });
    }
    // Staff sign-in codes have their own hourly budget at the notifier: anonymous visitors triggering demo
    // codes (the demo password is public) must never use up the admin's ability to sign in.
    if (!(await sendCode(r, r.template === 'staff-login' ? 'staff' : 'citizen'))) {
      req.log?.error({ key: m.key.split(':')[0] }, 'one-time code could not be delivered');
      throw httpError(503, 'code_not_sent', 'The code could not be sent. Try again in a minute.');
    }
    return {};
  }
  return { test_code: m.code, test_message: codeText(r, ORIGIN) };
}
